<script setup lang="ts">
import{computed,ref}from'vue';import{state}from'../store';import{clubNews,brand}from'../brand';import MemberComparison from'../components/MemberComparison.vue';import{clubProfile as profile}from'../clubProfile';import Icon from'../components/Icon.vue';import ActivityCard from'../components/ActivityCard.vue';import{useRouter}from'vue-router'
const router=useRouter(),guide=ref(false)
const upcoming=computed(()=>state.activities.filter(a=>a.status==='PUBLISHED'&&new Date(a.endsAt).getTime()>Date.now()).sort((a,b)=>+new Date(a.startsAt)-+new Date(b.startsAt)))
const stats=computed(()=>[{label:'同行骑友',value:state.overview.memberCount,unit:'人',icon:'users'},{label:'骑行与训练',value:state.overview.activityCount,unit:'场',icon:'bike'},{label:'成立年份',value:profile.founded,unit:'年',icon:'calendar'},{label:'登记器材',value:state.overview.equipmentCount,unit:'件',icon:'package'}])
</script>
<template><div class="page-content zt-home"><div class="zt-kicker"><span class="system-dot"/>{{brand.fullName}}<span>热爱不设终点</span></div>
<section class="zt-hero"><img src="/images/zhengtu-team.jpg" alt="征途单车俱乐部车队合影（简介资料图）"><div class="zt-hero-shade"/><div class="zt-hero-copy"><span class="zt-pill"><Icon name="bike" :size="16"/>2013 年启程 · 与热爱同行</span><h1>把热爱，<br>骑成<span>征途。</span></h1><p>一辆单车，一群伙伴，一段共同的征途。<br>在骑行中遇见风景，也遇见更好的自己。</p><div class="zt-actions"><router-link to="/clubs" class="zt-primary">了解征途 · 申请加入<Icon name="arrowup" :size="18"/></router-link><router-link to="/activities" class="zt-secondary">查看骑行活动<Icon name="arrow" :size="17"/></router-link></div></div><div class="zt-hero-foot"><span>俱乐部车队合影 · 简介资料图</span><span>安全同行 · 热爱骑行 · 一起成长</span></div></section>
<div class="zt-stat-grid"><div v-for="s in stats" :key="s.label"><span><Icon :name="s.icon" :size="17"/>{{s.label}}</span><b>{{s.value??0}}<small>{{s.unit}}</small></b></div></div>
<MemberComparison/><section class="zt-story"><div><div class="eyebrow">关于征途</div><h2>从校园出发，<br>让世界成为你的风景。</h2></div><div><p>{{profile.brief}}</p><router-link to="/clubs" class="text-link">认识征途单车俱乐部<Icon name="arrow" :size="17"/></router-link></div><div class="zt-values"><span><Icon name="shield"/>安全同行</span><span><Icon name="users"/>团队协作</span><span><Icon name="mountain"/>探索成长</span></div></section>
<section class="home-section"><div class="section-heading"><div><div class="eyebrow">下一程，一起出发</div><h2>骑行与活动</h2><p>活动发布、在线报名、现场签到，每一次参与都有记录。</p></div><router-link to="/activities" class="outline-link">全部活动<Icon name="arrowup" :size="16"/></router-link></div><div v-if="upcoming.length" class="activity-grid"><ActivityCard v-for="a in upcoming.slice(0,3)" :key="a.id" :activity="a" @select="router.push({path:'/activities',query:{activity:a.id}})"/></div><div v-else class="zt-empty-ride panel"><Icon name="bike" :size="45"/><div><h3>下一次出发，正在准备中</h3><p>正式活动由管理员发布，时间、路线与集合地点以活动详情为准。</p></div><router-link :to="state.user?.role==='ADMIN'?'/admin':'/activities'" class="text-link">{{state.user?.role==='ADMIN'?'前往后台发布活动':'查看活动记录'}}<Icon name="arrow" :size="17"/></router-link></div></section>
<section class="zt-news"><div class="section-heading"><div><div class="eyebrow">被记录的热爱</div><h2>征途 · 赛场与故事</h2><p>来自学校官网的俱乐部报道。</p></div><Icon name="trend" :size="29"/></div><div class="zt-news-grid"><a v-for="(n,i) in clubNews" :key="n.url" :href="n.url" target="_blank" rel="noopener noreferrer" class="zt-news-card"><div class="zt-news-number">0{{i+1}}<Icon name="arrowup" :size="25"/></div><span class="category-label">{{n.tag}} · {{n.date}}</span><h3>{{n.title}}</h3><p>{{n.summary}}</p><span class="text-link">阅读学校原文<Icon name="arrow" :size="16"/></span></a></div></section>
<section class="zt-services"><router-link to="/equipment"><span class="stat-icon green"><Icon name="package" :size="25"/></span><div><h3>器材共享，轻装出发</h3><p>器材登记 · 借用审批 · 归还验收</p></div><Icon name="arrowup"/></router-link><router-link to="/repairs"><span class="stat-icon orange"><Icon name="wrench" :size="25"/></span><div><h3>器材报修，全程可查</h3><p>提交工单 · 跟踪进度 · 维修记录</p></div><Icon name="arrowup"/></router-link></section>
<div class="zt-join-banner"><div><span class="eyebrow">不必一个人出发</span><h2>下一段征途，期待有你。</h2></div><button class="zt-primary" @click="guide=true">第一次加入？查看指引<Icon name="arrowup" :size="18"/></button></div></div>
<el-dialog v-model="guide" title="征途入社与活动指引" width="min(590px,94vw)"><div class="guide-content"><h3>01 · 提交入社申请</h3><p>注册时选择加入俱乐部或社团并填写资料，招新开放时会提交待审核申请。已有账号可在俱乐部展示申请加入或查看审核结果；成员中心仅保留身份状态和活动、借还记录。</p><h3>02 · 报名与签到</h3><p>查看已发布活动的时间、集合地点和说明，按需报名。签到开放期间，在成员中心输入现场负责人提供的签到码。</p><h3>03 · 器材借还与报修</h3><p>按实际库存申请器材，经审核后领取；使用后提交归还申请，等待管理员验收。器材问题可在线提交报修工单。</p><h3>出发前</h3><p>请阅读具体活动安排，检查车辆与装备，遵守交通规则。未发布的路线、时间和联系方式以俱乐部确认信息为准。</p></div><template #footer><el-button type="primary" @click="guide=false;router.push('/clubs')">前往入社申请</el-button></template></el-dialog></template>
